/**
 * Eye-local coordinate system (ELC) shared by all rehabilitation renderers
 * (2D illustration, 3D avatar, camera guide) and by the exercise data.
 *
 *   origin = centre of the AFFECTED eye (midpoint of the canthi)
 *   x      = towards the affected ear (outward, +), towards the nose (−)
 *   y      = up (+)
 *   unit   = half the palpebral width (inner canthus = (−1, 0), outer = (1, 0))
 *
 * Feature positions below were measured with MediaPipe face landmarks on the
 * Hallym reference frames (mean over close-up frames), so contact points
 * measured in the same system land on the same anatomy in every renderer.
 */
export type Pt = readonly [number, number];

/** Facial midline in ELC (nose tip x). */
export const XM = -2.3;
/** Mirror a point to the healthy side. */
export const mirror = ([x, y]: Pt): Pt => [2 * XM - x, y];

/** Reference anatomy (measured means; see docs/04 §9). */
