export type MuscleShape =
  { type: 'ring'; c: Pt; rIn: Pt; rOut: Pt } | { type: 'strip'; path: Pt[]; width: number } | { type: 'sheet'; poly: Pt[]; fibre: Pt };

export interface Muscle {
  name: string;
  latin: string;
  shapes: MuscleShape[];
  /** Where the muscle name label is placed. */
  label: Pt;
}

